/**
 * @telnyx/react-native-voice-sdk публикует сырые .ts-исходники вместо .d.ts, и
 * `tsc` проверяет их со строгими настройками проекта — там десятки ошибок, на
 * которые мы повлиять не можем (skipLibCheck на .ts не действует).
 *
 * Напрямую мы этот пакет не используем: работаем через @telnyx/react-voice-commons-sdk,
 * который лишь реэкспортирует из него пару типов. Поэтому tsconfig `paths`
 * подменяет его этим описанием-заглушкой. В рантайме Metro берёт настоящий пакет.
 */
declare const sdk: any;
export = sdk;
